tool_calls:
mkdir -p /app
awk '
FNR == NR {
    pos = index($0, "=")
    if (pos) {
        key = substr($0, 1, pos - 1)
        overrides[key] = substr($0, pos + 1)
    }
    next
}
{
    pos = index($0, "=")
    if (!pos) next
    key = substr($0, 1, pos - 1)
    value = substr($0, pos + 1)
    if (key in overrides) {
        value = overrides[key]
    } else if (value ~ /^\$\{[^:}]+:-.*\}$/) {
        sub(/^\$\{[^:}]+:-/, "", value)
        sub(/\}$/, "", value)
    }
    print key "=" value
}
' /config/overrides.txt /config/template.env > /app/.env
cat /app/.env

tool_outputs.stdout:
DB_HOST=${DB_HOST:-localhost}
DB_PORT=${DB_PORT:-5432}
DB_NAME=${DB_NAME:-myapp}
REDIS_URL=${REDIS_URL:-redis://localhost:6379}
LOG_LEVEL=${LOG_LEVEL:-info}

